import path from 'node:path'

/**
 * Resolve a relative path below the workspace root.
 *
 * @param {string} root - The workspace root path. Can be abs or relative.
 * @param {string} value - The path to resolve. Must be relative.
 * @returns {string} The resolved absolute path.
 * @throws {Error} If `value` is absolute or would escape the root.
 */
export function resolveRelative(root, value) {
  // If value is already absolute, disallow
  if (path.isAbsolute(value)) {
    throw new Error(`Path escapes the workspace: ${value}`)
  }

  // Resolve against the root; this yields an absolute path (based on cwd if root is relative)
  const resolved = path.resolve(root, value)

  // Determine if resolved path escapes the root
  const relativeFromRoot = path.relative(root, resolved)
  // path.relative may produce '..' at start if outside
  if (relativeFromRoot.startsWith('..') || relativeFromRoot === '..') {
    throw new Error(`Path escapes the workspace: ${value}`)
  }

  return resolved
}
